CREATE TABLE "identities" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "source" varchar(40) NOT NULL, "external_user_id" varchar(128) NOT NULL, "display_name" varchar(120) NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "identities_source_external_unique" ON "identities" USING btree ("source","external_user_id");
CREATE TABLE "conversations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "pair_key" varchar(300) NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "last_activity_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "conversations_pair_key_unique" UNIQUE("pair_key"));
CREATE TABLE "conversation_participants" ("conversation_id" uuid NOT NULL REFERENCES "conversations"("id") ON DELETE cascade, "identity_id" uuid NOT NULL REFERENCES "identities"("id") ON DELETE cascade, "last_read_at" timestamp with time zone, CONSTRAINT "conversation_participants_conversation_id_identity_id_pk" PRIMARY KEY("conversation_id","identity_id"));
CREATE TABLE "media_messages" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "conversation_id" uuid NOT NULL REFERENCES "conversations"("id") ON DELETE cascade, "sender_identity_id" uuid NOT NULL REFERENCES "identities"("id"), "media_type" varchar(10) NOT NULL, "object_key" varchar(512) NOT NULL, "content_type" varchar(100) NOT NULL, "byte_size" bigint NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, CONSTRAINT "media_messages_object_key_unique" UNIQUE("object_key"));
CREATE INDEX "media_messages_conversation_created_idx" ON "media_messages" USING btree ("conversation_id","created_at");
